{"query":"

  query Segments(
    $segmentIds: [Identifier!]!
    $leaderboardTypes: [SegmentLeaderTypeInput!]
  ) {
    segments(segmentIds: $segmentIds) {
      metadata {
        name
        activityType
        climbCategory
        verifiedStatus
      }
      measurements {
        distance
        avgGrade
        elevHigh
        elevLow
      }
      elevationChart {
        url
      }
      totalAthletes
      totalEfforts
      athletePrEffort {
        timing {
          elapsedTime
        }
        activity {
          id
        }
      }
      leaderboards(leaderboardTypes: $leaderboardTypes) {
        leaderboardEfforts {
          athlete {
            id
            firstName
            lastName
          }
          activity {
            id
          }
          timing {
            elapsedTime
          }
        }
      }
    }
  }

